<script module lang="ts">
/**
 * Immediate on/off setting (`design/components/switch.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/switch.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/switch'
import { useMachine } from '@zag-js/svelte'

import { agentMember, joinSlot, normalizeProps, useDirection, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/switch.module.css'

export interface SwitchProps {
  'aria-describedby'?: string
  'aria-label'?: string
  /**
   * Names the switch from a label elsewhere on the page, such as `SettingsRow`'s row label,
   * which is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  checked?: boolean
  defaultChecked?: boolean
  disabled?: boolean
  id?: string
  /**
   * Visible inline label. Omit it only when the context labels the switch, and then `aria-label`
   * is required.
   */
  label?: string
  name?: string
  onCheckedChange?: (checked: boolean) => void
  value?: string
}

export const controlKind = 'row-labelled'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  checked,
  defaultChecked,
  disabled = false,
  id: idOwn,
  label: labelOwn,
  name,
  onCheckedChange,
  value,
}: SwitchProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, label: labelOwn, name: name }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let track = $state<HTMLElement | null>(null)
const documentDirection = useDirection(() => track)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      checked: checked,
      defaultChecked: defaultChecked,
      disabled: disabled,
      required: ariaRequired,
      name: name,
      value: value,
      onCheckedChange: (details) => {
        onCheckedChange?.(details.checked)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const dataState = $derived(api.checked ? 'on' : 'off')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Switch',
    element: () => track,
    state: () => ({ checked: api.checked, disabled: disabled }),
    actions: { check: () => api.setChecked(true), uncheck: () => api.setChecked(false) },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if label === undefined
    }<button
      bind:this={track}
      class={styles.track}
      type="button"
      role="switch"
      {id}
      aria-checked={api.checked}
      {disabled}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
      data-state={dataState}
      data-disabled={(disabled) ? '' : undefined}
      data-required={(ariaRequired) ? '' : undefined}
      data-member="switch"
      onclick={() => { api.toggleChecked() }}
      ><span class={styles.thumb} data-state={dataState}></span
    ></button
  >{:else
    }<label
      class={styles.row}
      data-state={dataState}
      data-disabled={(disabled) ? '' : undefined}
      data-required={(ariaRequired) ? '' : undefined}
      data-member="switch"
      ><button
        bind:this={track}
        class={styles.track}
        type="button"
        role="switch"
        {id}
        aria-checked={api.checked}
        {disabled}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledby}
        aria-describedby={ariaDescribedby}
        aria-required={ariaRequired}
        data-state={dataState}
        data-disabled={(disabled) ? '' : undefined}
        data-required={(ariaRequired) ? '' : undefined}
        data-member="switch"
        onclick={() => { api.toggleChecked() }}
        ><span class={styles.thumb} data-state={dataState}></span
      ></button
      ><span class={styles.label}>{label}</span
    ></label
  >{/if
  }{#if name !== undefined && api.checked}<input type="hidden" {name} value={value ?? 'on'} />{/if
}{/if
}{@render joined.end?.()}
